import os
import sys
import fire
from PyPDF2 import PdfReader

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
from _log import log_tool_call


def _read_file(pdf_file_path):
    reader = PdfReader(pdf_file_path)
    text = ""
    for page in reader.pages:
        text += page.extract_text()
    return text


@log_tool_call("pdf.read_file")
def main(pdf_file_path):
    if not os.path.exists(pdf_file_path):
        return f"OBSERVATION: The pdf file {pdf_file_path} does not exist. Failed to read the file."
    return "OBSERVATION: " + _read_file(pdf_file_path)


if __name__ == "__main__":
    fire.Fire(main)

import os
import sys
import fire
import subprocess

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
from _log import log_tool_call

TESTBED_DIR = os.environ.get("OFFICEBENCH_TESTBED", "/workspace/testbed")


@log_tool_call("shell.command")
def main(command):
    if isinstance(command, list):
        command = " ".join(command)
    try:
        result = subprocess.run(
            command, shell=True, capture_output=True, text=True, cwd=TESTBED_DIR
        )
        output = result.stdout + result.stderr
        return f"OBSERVATION: Successfully executed command: {command}. The output was [{output}]."
    except Exception as e:
        return f"OBSERVATION: Failed to execute command: {command}. Error: {e}"


if __name__ == "__main__":
    fire.Fire(main)

import os
import sys
import fire
import openpyxl

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
from _log import log_tool_call


def _create_new_file(file_path):
    try:
        os.makedirs(os.path.dirname(file_path), exist_ok=True)
        wb = openpyxl.Workbook()
        wb.active.title = "Sheet"
        wb.save(file_path)
        return True
    except Exception:
        return False


@log_tool_call("excel.create_new_file")
def main(file_path):
    if os.path.exists(file_path):
        return f"OBSERVATION: File {file_path} already exists"
    success = _create_new_file(file_path)
    if success:
        return f"OBSERVATION: Successfully create new file {file_path}"
    return f"OBSERVATION: Failed to create new file {file_path}"


if __name__ == "__main__":
    fire.Fire(main)

